insert into public.questions (id, subject, grade, chapter, topic, type, level, pool, data, owner_id) values
('10-1-01', 'toan', 10, '10-1', 'Mệnh đề', 'mcq', 'NB', 'practice', $q${"id":"10-1-01","grade":10,"chapter":"10-1","topic":"Mệnh đề","type":"mcq","level":"NB","difficulty":1,"source":"Tự biên soạn","content":"Câu nào sau đây là một mệnh đề?","options":["Hôm nay trời đẹp quá!","$x+1>3$","Số $7$ là số nguyên tố.","Bạn có đi học không?"],"answer":2,"explanation":"Mệnh đề là câu khẳng định có tính đúng hoặc sai xác định. \"Số 7 là số nguyên tố\" là mệnh đề đúng; câu cảm thán, câu hỏi không phải mệnh đề; $x+1>3$ là mệnh đề chứa biến.","pool":"practice"}$q$::jsonb, null),
('10-1-02', 'toan', 10, '10-1', 'Tập hợp và các phép toán trên tập hợp', 'mcq', 'NB', 'practice', $q${"id":"10-1-02","grade":10,"chapter":"10-1","topic":"Tập hợp và các phép toán trên tập hợp","type":"mcq","level":"NB","difficulty":1,"source":"Tự biên soạn","content":"Cho $A=\\{1;2;3;4\\}$ và $B=\\{3;4;5\\}$. Tập hợp $A\\cap B$ là","options":["$\\{3;4\\}$","$\\{1;2\\}$","$\\{1;2;3;4;5\\}$","$\\{5\\}$"],"answer":0,"explanation":"$A\\cap B$ gồm các phần tử thuộc cả $A$ và $B$, đó là $3$ và $4$.","pool":"practice"}$q$::jsonb, null),
('10-1-03', 'toan', 10, '10-1', 'Mệnh đề', 'mcq', 'TH', 'practice', $q${"id":"10-1-03","grade":10,"chapter":"10-1","topic":"Mệnh đề","type":"mcq","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Mệnh đề phủ định của mệnh đề \"$\\forall x\\in\\mathbb{R},\\ x^2+1>0$\" là","options":["$\\forall x\\in\\mathbb{R},\\ x^2+1\\le 0$","$\\exists x\\in\\mathbb{R},\\ x^2+1\\le 0$","$\\exists x\\in\\mathbb{R},\\ x^2+1<0$","$\\exists x\\in\\mathbb{R},\\ x^2+1>0$"],"answer":1,"explanation":"Phủ định của \"$\\forall x, P(x)$\" là \"$\\exists x, \\overline{P(x)}$\"; phủ định của $x^2+1>0$ là $x^2+1\\le 0$.","pool":"practice"}$q$::jsonb, null),
('10-1-04', 'toan', 10, '10-1', 'Tập hợp và các phép toán trên tập hợp', 'mcq', 'VD', 'practice', $q${"id":"10-1-04","grade":10,"chapter":"10-1","topic":"Tập hợp và các phép toán trên tập hợp","type":"mcq","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Một lớp có $40$ học sinh, trong đó $25$ em thích bóng đá, $18$ em thích cầu lông và $7$ em không thích môn nào trong hai môn trên. Số học sinh thích cả hai môn là","options":["$7$","$8$","$12$","$10$"],"answer":3,"explanation":"Số em thích ít nhất một môn là $40-7=33$. Ta có $25+18-x=33\\Rightarrow x=10$.","pool":"practice"}$q$::jsonb, null),
('10-1-05', 'toan', 10, '10-1', 'Tập hợp và các phép toán trên tập hợp', 'tf', 'TH', 'practice', $q${"id":"10-1-05","grade":10,"chapter":"10-1","topic":"Tập hợp và các phép toán trên tập hợp","type":"tf","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Cho hai tập hợp $A=[-1;3)$ và $B=(1;5]$. Xét tính đúng sai của các mệnh đề sau:","statements":["$A\\cap B=(1;3)$.","$A\\cup B=[-1;5]$.","$A\\setminus B=[-1;1)$.","$\\mathbb{R}\\setminus A=(-\\infty;-1)\\cup(3;+\\infty)$."],"answer":[true,true,false,false],"explanation":"a) Đúng. b) Đúng. c) Sai: vì $1\\notin B$ nên $A\\setminus B=[-1;1]$. d) Sai: $3\\notin A$ nên $\\mathbb{R}\\setminus A=(-\\infty;-1)\\cup[3;+\\infty)$.","pool":"practice"}$q$::jsonb, null),
('10-1-06', 'toan', 10, '10-1', 'Tập hợp và các phép toán trên tập hợp', 'short', 'TH', 'practice', $q${"id":"10-1-06","grade":10,"chapter":"10-1","topic":"Tập hợp và các phép toán trên tập hợp","type":"short","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Cho tập hợp $A=\\{x\\in\\mathbb{N}\\mid x<5\\}$. Tập hợp $A$ có bao nhiêu tập con?","answer":"32","explanation":"$A=\\{0;1;2;3;4\\}$ có $5$ phần tử nên có $2^5=32$ tập con.","pool":"practice"}$q$::jsonb, null),
('10-1-07', 'toan', 10, '10-1', 'Tập hợp và các phép toán trên tập hợp', 'short', 'VD', 'practice', $q${"id":"10-1-07","grade":10,"chapter":"10-1","topic":"Tập hợp và các phép toán trên tập hợp","type":"short","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Cho $A=[m;m+3]$ và $B=(0;10)$. Có bao nhiêu giá trị nguyên của $m$ để $A\\subset B$?","answer":"6","explanation":"$A\\subset B\\Leftrightarrow m>0$ và $m+3<10\\Leftrightarrow 0<m<7$. Các số nguyên: $1;2;3;4;5;6$, gồm $6$ giá trị.","pool":"practice"}$q$::jsonb, null),
('10-1-08', 'toan', 10, '10-1', 'Tập hợp và các phép toán trên tập hợp', 'essay', 'VD', 'practice', $q${"id":"10-1-08","grade":10,"chapter":"10-1","topic":"Tập hợp và các phép toán trên tập hợp","type":"essay","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Một lớp có $45$ học sinh. Kết quả khảo sát: $20$ em giỏi Toán, $18$ em giỏi Văn, $15$ em giỏi Anh; $7$ em giỏi cả Toán và Văn, $6$ em giỏi cả Toán và Anh, $5$ em giỏi cả Văn và Anh; $3$ em giỏi cả ba môn.\na) Có bao nhiêu học sinh không giỏi môn nào trong ba môn trên?\nb) Có bao nhiêu học sinh giỏi đúng một môn?","answer":"a) 7 học sinh; b) 26 học sinh.","explanation":"a) Số em giỏi ít nhất một môn: $20+18+15-7-6-5+3=38$. Số em không giỏi môn nào: $45-38=7$.\nb) Chỉ giỏi Toán: $20-7-6+3=10$; chỉ giỏi Văn: $18-7-5+3=9$; chỉ giỏi Anh: $15-6-5+3=7$. Tổng: $10+9+7=26$.","pool":"practice"}$q$::jsonb, null),
('10-2-01', 'toan', 10, '10-2', 'Bất phương trình bậc nhất hai ẩn', 'mcq', 'NB', 'practice', $q${"id":"10-2-01","grade":10,"chapter":"10-2","topic":"Bất phương trình bậc nhất hai ẩn","type":"mcq","level":"NB","difficulty":1,"source":"Tự biên soạn","content":"Bất phương trình nào sau đây là bất phương trình bậc nhất hai ẩn?","options":["$x^2+y>1$","$xy-2\\ge 0$","$2x-3y+1>0$","$2x+\\dfrac{1}{y}<3$"],"answer":2,"explanation":"Bất phương trình bậc nhất hai ẩn có dạng $ax+by+c>0$ (hoặc $<,\\ \\ge,\\ \\le$) với $a,b$ không đồng thời bằng $0$.","pool":"practice"}$q$::jsonb, null),
('10-2-02', 'toan', 10, '10-2', 'Bất phương trình bậc nhất hai ẩn', 'mcq', 'NB', 'practice', $q${"id":"10-2-02","grade":10,"chapter":"10-2","topic":"Bất phương trình bậc nhất hai ẩn","type":"mcq","level":"NB","difficulty":1,"source":"Tự biên soạn","content":"Cặp số nào sau đây là một nghiệm của bất phương trình $x+2y<4$?","options":["$(2;1)$","$(0;2)$","$(3;1)$","$(1;1)$"],"answer":3,"explanation":"Thay $(1;1)$: $1+2=3<4$ (đúng). Các cặp còn lại cho $4<4$, $4<4$, $5<4$ đều sai.","pool":"practice"}$q$::jsonb, null),
('10-2-03', 'toan', 10, '10-2', 'Bất phương trình bậc nhất hai ẩn', 'mcq', 'TH', 'practice', $q${"id":"10-2-03","grade":10,"chapter":"10-2","topic":"Bất phương trình bậc nhất hai ẩn","type":"mcq","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Gốc tọa độ $O(0;0)$ thuộc miền nghiệm của bất phương trình nào sau đây?","options":["$x+y>1$","$2x-y<3$","$x-3y\\ge 2$","$-x+y>0$"],"answer":1,"explanation":"Thay $x=0,\\ y=0$: chỉ có $0<3$ là đúng.","pool":"practice"}$q$::jsonb, null),
('10-2-04', 'toan', 10, '10-2', 'Hệ bất phương trình bậc nhất hai ẩn', 'mcq', 'VD', 'practice', $q${"id":"10-2-04","grade":10,"chapter":"10-2","topic":"Hệ bất phương trình bậc nhất hai ẩn","type":"mcq","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Giá trị lớn nhất của biểu thức $F=3x+2y$ trên miền nghiệm của hệ gồm các bất phương trình $x\\ge 0$, $y\\ge 0$, $x+y\\le 4$, $x+2y\\le 6$ là","options":["$10$","$12$","$6$","$14$"],"answer":1,"explanation":"Miền nghiệm là tứ giác với các đỉnh $(0;0),(4;0),(2;2),(0;3)$. Giá trị $F$ lần lượt: $0;12;10;6$. Vậy $\\max F=12$.","pool":"practice"}$q$::jsonb, null),
('10-2-05', 'toan', 10, '10-2', 'Hệ bất phương trình bậc nhất hai ẩn', 'tf', 'TH', 'practice', $q${"id":"10-2-05","grade":10,"chapter":"10-2","topic":"Hệ bất phương trình bậc nhất hai ẩn","type":"tf","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Cho hệ bất phương trình gồm $x+y\\le 3$, $x-y\\ge -1$ và $y\\ge 0$. Xét tính đúng sai của các mệnh đề sau:","statements":["Điểm $(1;1)$ thuộc miền nghiệm của hệ.","Điểm $(0;2)$ thuộc miền nghiệm của hệ.","Miền nghiệm của hệ là tam giác có các đỉnh $(-1;0)$, $(3;0)$, $(1;2)$.","Giá trị lớn nhất của $F=x+2y$ trên miền nghiệm bằng $4$."],"answer":[true,false,true,false],"explanation":"a) Đúng: $2\\le 3$, $0\\ge -1$, $1\\ge 0$. b) Sai: $0-2=-2<-1$. c) Đúng: giao điểm từng cặp đường thẳng $x+y=3$, $x-y=-1$, $y=0$. d) Sai: $F$ tại các đỉnh là $-1;3;5$ nên $\\max F=5$.","pool":"practice"}$q$::jsonb, null),
('10-2-06', 'toan', 10, '10-2', 'Hệ bất phương trình bậc nhất hai ẩn', 'short', 'TH', 'practice', $q${"id":"10-2-06","grade":10,"chapter":"10-2","topic":"Hệ bất phương trình bậc nhất hai ẩn","type":"short","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Tính diện tích miền nghiệm của hệ bất phương trình gồm $x\\ge 0$, $y\\ge 0$, $2x+y\\le 6$.","answer":"9","explanation":"Miền nghiệm là tam giác vuông có đỉnh $(0;0),(3;0),(0;6)$. Diện tích $\\dfrac{1}{2}\\cdot 3\\cdot 6=9$.","pool":"practice"}$q$::jsonb, null),
('10-2-07', 'toan', 10, '10-2', 'Hệ bất phương trình bậc nhất hai ẩn', 'short', 'VD', 'practice', $q${"id":"10-2-07","grade":10,"chapter":"10-2","topic":"Hệ bất phương trình bậc nhất hai ẩn","type":"short","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Một xưởng sản xuất hai loại sản phẩm A và B. Mỗi sản phẩm A cần $2$ giờ trên máy I và $1$ giờ trên máy II, lãi $3$ triệu đồng; mỗi sản phẩm B cần $1$ giờ trên máy I và $1$ giờ trên máy II, lãi $2$ triệu đồng. Trong một ngày máy I làm tối đa $10$ giờ, máy II làm tối đa $7$ giờ. Tiền lãi lớn nhất xưởng có thể thu được trong một ngày là bao nhiêu triệu đồng?","answer":"17","explanation":"Gọi $x,y$ là số sản phẩm A, B. Điều kiện: $x,y\\ge 0$, $2x+y\\le 10$, $x+y\\le 7$. Lãi $F=3x+2y$. Các đỉnh: $(0;0),(5;0),(3;4),(0;7)$ với $F$ lần lượt $0;15;17;14$. Vậy lãi lớn nhất $17$ triệu đồng.","pool":"practice"}$q$::jsonb, null),
('10-2-08', 'toan', 10, '10-2', 'Hệ bất phương trình bậc nhất hai ẩn', 'essay', 'VD', 'practice', $q${"id":"10-2-08","grade":10,"chapter":"10-2","topic":"Hệ bất phương trình bậc nhất hai ẩn","type":"essay","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Một trang trại cần mỗi ngày ít nhất $12$ đơn vị chất dinh dưỡng P và $8$ đơn vị chất dinh dưỡng Q cho đàn gia súc. Mỗi bao thức ăn loại X chứa $3$ đơn vị P, $1$ đơn vị Q và có giá $200$ nghìn đồng; mỗi bao thức ăn loại Y chứa $2$ đơn vị P, $2$ đơn vị Q và có giá $250$ nghìn đồng. Hỏi trang trại cần mua bao nhiêu bao mỗi loại để chi phí là nhỏ nhất?","answer":"Mua 2 bao X và 3 bao Y; chi phí nhỏ nhất 1 150 nghìn đồng.","explanation":"Gọi $x,y$ là số bao X, Y ($x,y\\ge 0$). Điều kiện: $3x+2y\\ge 12$, $x+2y\\ge 8$. Chi phí $T=200x+250y$ (nghìn đồng).\nMiền nghiệm không bị chặn, có các đỉnh $(0;6)$, $(2;3)$, $(8;0)$ (giao của $3x+2y=12$ và $x+2y=8$ là $(2;3)$).\n$T(0;6)=1500$, $T(2;3)=1150$, $T(8;0)=1600$. Do các hệ số của $T$ dương nên giá trị nhỏ nhất đạt tại đỉnh: $T_{\\min}=1150$ khi $x=2,\\ y=3$.","pool":"practice"}$q$::jsonb, null),
('10-3-01', 'toan', 10, '10-3', 'Giá trị lượng giác của một góc từ 0° đến 180°', 'mcq', 'NB', 'practice', $q${"id":"10-3-01","grade":10,"chapter":"10-3","topic":"Giá trị lượng giác của một góc từ 0° đến 180°","type":"mcq","level":"NB","difficulty":1,"source":"Tự biên soạn","content":"Giá trị của $\\sin 150^\\circ$ bằng","options":["$-\\dfrac{1}{2}$","$\\dfrac{\\sqrt{3}}{2}$","$\\dfrac{1}{2}$","$-\\dfrac{\\sqrt{3}}{2}$"],"answer":2,"explanation":"$\\sin 150^\\circ=\\sin(180^\\circ-30^\\circ)=\\sin 30^\\circ=\\dfrac{1}{2}$.","pool":"practice"}$q$::jsonb, null),
('10-3-02', 'toan', 10, '10-3', 'Hệ thức lượng trong tam giác', 'mcq', 'NB', 'practice', $q${"id":"10-3-02","grade":10,"chapter":"10-3","topic":"Hệ thức lượng trong tam giác","type":"mcq","level":"NB","difficulty":1,"source":"Tự biên soạn","content":"Cho tam giác $ABC$ có $BC=a$, $CA=b$, $AB=c$. Khẳng định nào sau đây đúng?","options":["$a^2=b^2+c^2-2bc\\cos A$","$a^2=b^2+c^2+2bc\\cos A$","$a^2=b^2+c^2-bc\\cos A$","$a^2=b^2+c^2-2bc\\sin A$"],"answer":0,"explanation":"Định lí côsin: $a^2=b^2+c^2-2bc\\cos A$.","pool":"practice"}$q$::jsonb, null),
('10-3-03', 'toan', 10, '10-3', 'Hệ thức lượng trong tam giác', 'mcq', 'TH', 'practice', $q${"id":"10-3-03","grade":10,"chapter":"10-3","topic":"Hệ thức lượng trong tam giác","type":"mcq","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Tam giác $ABC$ có $AC=4$, $AB=5$ và $\\widehat{BAC}=60^\\circ$. Độ dài cạnh $BC$ là","options":["$\\sqrt{61}$","$21$","$\\sqrt{41}$","$\\sqrt{21}$"],"answer":3,"explanation":"$BC^2=4^2+5^2-2\\cdot4\\cdot5\\cos 60^\\circ=41-20=21\\Rightarrow BC=\\sqrt{21}$.","pool":"practice"}$q$::jsonb, null),
('10-3-04', 'toan', 10, '10-3', 'Hệ thức lượng trong tam giác', 'mcq', 'VD', 'practice', $q${"id":"10-3-04","grade":10,"chapter":"10-3","topic":"Hệ thức lượng trong tam giác","type":"mcq","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Tam giác $ABC$ có ba cạnh $a=7$, $b=8$, $c=5$. Bán kính đường tròn ngoại tiếp tam giác bằng","options":["$\\dfrac{7\\sqrt{3}}{6}$","$\\dfrac{7\\sqrt{3}}{3}$","$7\\sqrt{3}$","$\\dfrac{14\\sqrt{3}}{3}$"],"answer":1,"explanation":"Nửa chu vi $p=10$, $S=\\sqrt{10\\cdot3\\cdot2\\cdot5}=10\\sqrt{3}$. $R=\\dfrac{abc}{4S}=\\dfrac{280}{40\\sqrt{3}}=\\dfrac{7\\sqrt{3}}{3}$.","pool":"practice"}$q$::jsonb, null),
('10-3-05', 'toan', 10, '10-3', 'Hệ thức lượng trong tam giác', 'tf', 'TH', 'practice', $q${"id":"10-3-05","grade":10,"chapter":"10-3","topic":"Hệ thức lượng trong tam giác","type":"tf","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Cho tam giác $ABC$ có $BC=6$, $\\widehat{B}=45^\\circ$, $\\widehat{C}=75^\\circ$. Xét tính đúng sai của các mệnh đề sau:","statements":["$\\widehat{A}=60^\\circ$.","Bán kính đường tròn ngoại tiếp tam giác $ABC$ bằng $2\\sqrt{3}$.","$AC=3\\sqrt{2}$.","Diện tích tam giác $ABC$ bằng $9+3\\sqrt{3}$."],"answer":[true,true,false,true],"explanation":"a) Đúng: $\\widehat{A}=180^\\circ-45^\\circ-75^\\circ=60^\\circ$. b) Đúng: $2R=\\dfrac{6}{\\sin60^\\circ}=4\\sqrt{3}$. c) Sai: $AC=2R\\sin B=4\\sqrt{3}\\cdot\\dfrac{\\sqrt{2}}{2}=2\\sqrt{6}$. d) Đúng: $S=\\dfrac{1}{2}\\cdot BC\\cdot AC\\cdot\\sin C=\\dfrac{1}{2}\\cdot6\\cdot2\\sqrt{6}\\cdot\\dfrac{\\sqrt{6}+\\sqrt{2}}{4}=9+3\\sqrt{3}$.","pool":"practice"}$q$::jsonb, null),
('10-3-06', 'toan', 10, '10-3', 'Hệ thức lượng trong tam giác', 'short', 'TH', 'practice', $q${"id":"10-3-06","grade":10,"chapter":"10-3","topic":"Hệ thức lượng trong tam giác","type":"short","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Tính diện tích tam giác có độ dài ba cạnh là $13$, $14$, $15$.","answer":"84","explanation":"$p=21$, $S=\\sqrt{21\\cdot8\\cdot7\\cdot6}=\\sqrt{7056}=84$.","pool":"practice"}$q$::jsonb, null),
('10-3-07', 'toan', 10, '10-3', 'Hệ thức lượng trong tam giác', 'short', 'VD', 'practice', $q${"id":"10-3-07","grade":10,"chapter":"10-3","topic":"Hệ thức lượng trong tam giác","type":"short","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Để đo chiều cao một tháp, người ta đứng tại hai điểm $A$, $B$ cách nhau $20$ m trên mặt đất, thẳng hàng với chân tháp ($B$ gần tháp hơn). Góc nâng nhìn lên đỉnh tháp từ $A$ là $30^\\circ$, từ $B$ là $45^\\circ$. Tính chiều cao của tháp (đơn vị: mét, làm tròn đến hàng phần mười).","answer":"27,3","explanation":"Gọi $h$ là chiều cao. Khoảng cách từ $A$, $B$ đến chân tháp lần lượt là $h\\sqrt{3}$ và $h$. Ta có $h\\sqrt{3}-h=20\\Rightarrow h=\\dfrac{20}{\\sqrt{3}-1}=10(\\sqrt{3}+1)\\approx 27{,}3$ m.","pool":"practice"}$q$::jsonb, null),
('10-3-08', 'toan', 10, '10-3', 'Hệ thức lượng trong tam giác', 'essay', 'VD', 'practice', $q${"id":"10-3-08","grade":10,"chapter":"10-3","topic":"Hệ thức lượng trong tam giác","type":"essay","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Hai tàu cùng xuất phát từ một cảng, đi theo hai hướng tạo với nhau góc $60^\\circ$. Tàu thứ nhất chạy với vận tốc $30$ km/h, tàu thứ hai chạy với vận tốc $40$ km/h. Hỏi sau $2$ giờ hai tàu cách nhau bao nhiêu kilômét (làm tròn đến hàng phần trăm)?","answer":"$20\\sqrt{13}\\approx 72{,}11$ km.","explanation":"Sau 2 giờ, hai tàu cách cảng lần lượt $60$ km và $80$ km. Theo định lí côsin: $d^2=60^2+80^2-2\\cdot60\\cdot80\\cos60^\\circ=10000-4800=5200$.\nVậy $d=\\sqrt{5200}=20\\sqrt{13}\\approx 72{,}11$ km.","pool":"practice"}$q$::jsonb, null),
('10-4-01', 'toan', 10, '10-4', 'Các khái niệm mở đầu', 'mcq', 'NB', 'practice', $q${"id":"10-4-01","grade":10,"chapter":"10-4","topic":"Các khái niệm mở đầu","type":"mcq","level":"NB","difficulty":1,"source":"Tự biên soạn","content":"Cho hình bình hành $ABCD$. Đẳng thức nào sau đây đúng?","options":["$\\overrightarrow{AB}=\\overrightarrow{CD}$","$\\overrightarrow{AB}=\\overrightarrow{DC}$","$\\overrightarrow{AD}=\\overrightarrow{CB}$","$\\overrightarrow{AC}=\\overrightarrow{BD}$"],"answer":1,"explanation":"Trong hình bình hành $ABCD$, hai vectơ $\\overrightarrow{AB}$ và $\\overrightarrow{DC}$ cùng hướng và cùng độ dài.","pool":"practice"}$q$::jsonb, null),
('10-4-02', 'toan', 10, '10-4', 'Vectơ trong mặt phẳng tọa độ', 'mcq', 'NB', 'practice', $q${"id":"10-4-02","grade":10,"chapter":"10-4","topic":"Vectơ trong mặt phẳng tọa độ","type":"mcq","level":"NB","difficulty":1,"source":"Tự biên soạn","content":"Cho $\\vec{a}=(2;-3)$ và $\\vec{b}=(1;4)$. Tọa độ của vectơ $\\vec{a}+\\vec{b}$ là","options":["$(1;-7)$","$(3;-1)$","$(3;1)$","$(2;-12)$"],"answer":2,"explanation":"$\\vec{a}+\\vec{b}=(2+1;-3+4)=(3;1)$.","pool":"practice"}$q$::jsonb, null),
('10-4-03', 'toan', 10, '10-4', 'Tích của một vectơ với một số', 'mcq', 'TH', 'practice', $q${"id":"10-4-03","grade":10,"chapter":"10-4","topic":"Tích của một vectơ với một số","type":"mcq","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Cho tam giác $ABC$ có trọng tâm $G$ và $M$ là trung điểm của $BC$. Khẳng định nào sau đây đúng?","options":["$\\overrightarrow{AG}=\\dfrac{1}{3}\\overrightarrow{AM}$","$\\overrightarrow{GA}=2\\overrightarrow{GM}$","$\\overrightarrow{AM}=2\\overrightarrow{AG}$","$\\overrightarrow{AG}=\\dfrac{2}{3}\\overrightarrow{AM}$"],"answer":3,"explanation":"$G$ nằm trên đoạn $AM$ và $AG=\\dfrac{2}{3}AM$, hai vectơ $\\overrightarrow{AG}$, $\\overrightarrow{AM}$ cùng hướng. Lưu ý $\\overrightarrow{GA}=-2\\overrightarrow{GM}$.","pool":"practice"}$q$::jsonb, null),
('10-4-04', 'toan', 10, '10-4', 'Tích vô hướng của hai vectơ', 'mcq', 'VD', 'practice', $q${"id":"10-4-04","grade":10,"chapter":"10-4","topic":"Tích vô hướng của hai vectơ","type":"mcq","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Trong mặt phẳng $Oxy$, cho $A(1;1)$, $B(3;2)$, $C(m;4)$. Giá trị của $m$ để tam giác $ABC$ vuông tại $A$ là","options":["$m=\\dfrac{1}{2}$","$m=-\\dfrac{1}{2}$","$m=-2$","$m=\\dfrac{5}{2}$"],"answer":1,"explanation":"$\\overrightarrow{AB}=(2;1)$, $\\overrightarrow{AC}=(m-1;3)$. Tam giác vuông tại $A\\Leftrightarrow\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=0\\Leftrightarrow 2(m-1)+3=0\\Leftrightarrow m=-\\dfrac{1}{2}$.","pool":"practice"}$q$::jsonb, null),
('10-4-05', 'toan', 10, '10-4', 'Vectơ trong mặt phẳng tọa độ', 'tf', 'TH', 'practice', $q${"id":"10-4-05","grade":10,"chapter":"10-4","topic":"Vectơ trong mặt phẳng tọa độ","type":"tf","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Trong mặt phẳng $Oxy$, cho ba điểm $A(1;2)$, $B(3;-2)$, $C(-1;0)$. Xét tính đúng sai của các mệnh đề sau:","statements":["Trung điểm của đoạn $AB$ là $I(2;0)$.","$\\overrightarrow{AB}=(-2;4)$.","Trọng tâm tam giác $ABC$ là $G(1;1)$.","$\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=4$."],"answer":[true,false,false,true],"explanation":"a) Đúng. b) Sai: $\\overrightarrow{AB}=(2;-4)$. c) Sai: $G\\left(\\dfrac{1+3-1}{3};\\dfrac{2-2+0}{3}\\right)=(1;0)$. d) Đúng: $\\overrightarrow{AC}=(-2;-2)$, $\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=-4+8=4$.","pool":"practice"}$q$::jsonb, null),
('10-4-06', 'toan', 10, '10-4', 'Tích vô hướng của hai vectơ', 'short', 'TH', 'practice', $q${"id":"10-4-06","grade":10,"chapter":"10-4","topic":"Tích vô hướng của hai vectơ","type":"short","level":"TH","difficulty":2,"source":"Tự biên soạn","content":"Cho $\\vec{a}=(1;2)$ và $\\vec{b}=(3;-1)$. Tính $\\vec{a}\\cdot(2\\vec{a}-\\vec{b})$.","answer":"9","explanation":"$2\\vec{a}-\\vec{b}=(-1;5)$, nên $\\vec{a}\\cdot(2\\vec{a}-\\vec{b})=1\\cdot(-1)+2\\cdot5=9$.","pool":"practice"}$q$::jsonb, null),
('10-4-07', 'toan', 10, '10-4', 'Tích vô hướng của hai vectơ', 'short', 'VD', 'practice', $q${"id":"10-4-07","grade":10,"chapter":"10-4","topic":"Tích vô hướng của hai vectơ","type":"short","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Cho $\\vec{u}=(1;3)$ và $\\vec{v}=(2;-1)$. Tính số đo góc giữa hai vectơ $\\vec{u}$ và $\\vec{v}$ (đơn vị: độ, làm tròn đến hàng đơn vị).","answer":"98","explanation":"$\\cos(\\vec{u},\\vec{v})=\\dfrac{2-3}{\\sqrt{10}\\cdot\\sqrt{5}}=-\\dfrac{1}{\\sqrt{50}}\\approx-0{,}1414$, suy ra góc $\\approx 98{,}13^\\circ\\approx 98^\\circ$.","pool":"practice"}$q$::jsonb, null),
('10-4-08', 'toan', 10, '10-4', 'Tích của một vectơ với một số', 'essay', 'VD', 'practice', $q${"id":"10-4-08","grade":10,"chapter":"10-4","topic":"Tích của một vectơ với một số","type":"essay","level":"VD","difficulty":3,"source":"Tự biên soạn","content":"Cho tam giác $ABC$ và điểm $M$ thuộc đoạn $BC$ sao cho $MB=2MC$.\na) Chứng minh rằng $\\overrightarrow{AM}=\\dfrac{1}{3}\\overrightarrow{AB}+\\dfrac{2}{3}\\overrightarrow{AC}$.\nb) Trong mặt phẳng $Oxy$, cho $A(1;0)$, $B(4;3)$, $C(1;6)$. Tìm tọa độ điểm $M$.","answer":"b) $M(2;5)$.","explanation":"a) Vì $M$ thuộc đoạn $BC$ và $BM=\\dfrac{2}{3}BC$ nên $\\overrightarrow{BM}=\\dfrac{2}{3}\\overrightarrow{BC}$. Do đó $\\overrightarrow{AM}=\\overrightarrow{AB}+\\dfrac{2}{3}(\\overrightarrow{AC}-\\overrightarrow{AB})=\\dfrac{1}{3}\\overrightarrow{AB}+\\dfrac{2}{3}\\overrightarrow{AC}$.\nb) Từ a) suy ra $M=\\dfrac{1}{3}B+\\dfrac{2}{3}C$ (theo tọa độ): $x_M=\\dfrac{4}{3}+\\dfrac{2}{3}=2$, $y_M=1+4=5$. Vậy $M(2;5)$.","pool":"practice"}$q$::jsonb, null),
